from gpiozero import LED, Button
from time import sleep
import random

leds = [LED(17), LED(27), LED(22)]
buttons = [Button(23), Button(24), Button(25)]

def flash(number):
    leds[number].on()
    sleep(0.4)
    leds[number].off()
    sleep(0.2)

def get_press():
    while True:
        for number in range(3):
            if buttons[number].is_pressed:
                flash(number)
                buttons[number].wait_for_release()
                return number
        sleep(0.01)

pattern = []
score = 0
playing = True

while playing:
    pattern.append(random.randint(0, 2))
    print("Round", score + 1)
    for number in pattern:
        flash(number)
    for number in pattern:
        if get_press() != number:
            playing = False
            break
    if playing:
        score = score + 1
        sleep(0.5)

for i in range(3):
    for led in leds:
        led.on()
    sleep(0.3)
    for led in leds:
        led.off()
    sleep(0.3)
print("Game over! Your score:", score)
